"""Independent P9-2.4 result/receipt pressure.

Run against a complete checkout using the hash-checked replay command in
implementation/phase-9-grcv4/tranche-2/P9-2.4-Review.md.

Repository adapter: no substituted providers or unavailable isolated bootstrap.
The supplied 495 scenario decisions and four characterizations are unchanged.

This constructs hand-authored records; it executes no solver, scientific
transaction, rollback engine, or profile. Expected content hashes below use
stdlib JSON only for explicit ASCII/small-exact-number fixtures. Expected
admission is independently specified. Production is used to build mutated
inputs only when noted, not to select expected decisions.
"""
from __future__ import annotations
import argparse,copy,hashlib,json,math,sys,traceback,itertools,collections
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--repo',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args()
sys.path[:0]=[str(a.repo/'src'),str(a.repo)]
from pygrc.models import grc_v4_state as st,grc_v4_step as sp,grc_v4_codec as c,grc_v4 as api
from pygrc.core.events import GRCEvent

ROWS=[]
FAIL=(TypeError,ValueError,UnicodeError,OverflowError)
def normalize(v):
 if type(v) is float and v.is_integer() and abs(v)<=2**53-1:return int(v)
 if isinstance(v,dict):return {k:normalize(x) for k,x in v.items()}
 if isinstance(v,(tuple,list)):return [normalize(x) for x in v]
 return v
def raw(v):return json.dumps(normalize(v),sort_keys=True,separators=(',',':'),ensure_ascii=True,allow_nan=False).encode()
def identity(prefix,v):return prefix+':'+hashlib.sha256(raw(v)).hexdigest()
def label(prefix,char='a'):return prefix+':'+char*64
def test(name,fn,expect='pass',category='guard'):
 row={'case':name,'category':category,'expected':expect}
 try:
  got=fn();row['actual']='accepted';row['passed']=expect!='reject'
  if got is not None:row['detail']=got
 except FAIL as e:
  row.update(actual='rejected',exception=type(e).__name__,message=str(e),passed=expect=='reject')
 except Exception as e:
  row.update(actual='unexpected_exception',exception=type(e).__name__,message=str(e),traceback=traceback.format_exc(),passed=False)
 ROWS.append(row)

def req(dt=0.25,operation='audit:step',context=None):
 return api.GRCV4StepRequestInput.from_payload({'schema_version':'grcv4-step-request-input-v1','operation_id':operation,'dt':dt,'context_value':{'a':[True,{'n':1}]} if context is None else context,'boundary_input':None,'external_source':None})
def scientific():
 return {'schema_version':'grcv4-scientific-state-v1','active_model_identity':label('grcv4-profile-sha256','1'),'graph_digest':label('grc-graph-sha256','2'),'orientation_identity':'tail-to-head','step_index':3,'time':0.75,'authoritative':{'C':[1,2],'W_A':None,'Z_4':None},'reset_digest':label('grcv4-reset-sha256','3'),'Q_target':3,'context_contract_id':'audit:context','context_value_digest':None}
def state_id(s):return identity('grcv4-state-sha256',s)
def life_id(s,ledger):return identity('grcv4-lifecycle-sha256',{'schema_version':'grcv4-lifecycle-envelope-v1','scientific_state_digest':state_id(s),'receipt_ids':[r['receipt_id'] for r in ledger]})
def core(source,target,operation='audit:step'):
 r={'operation_id':operation,'actual_charge_delta':0,'information_losses':[],'disposition':'committed','parent_receipt_ids':[],'resource_transform_digest':label('grcv4-resource-transform-sha256','4'),'history_bundle_digest':label('grcv4-history-map-sha256','5')}
 for prefix,s in [('source',source),('target',target)]:
  for k,v in {'state_digest':state_id(s),'graph_digest':s['graph_digest'],'model_identity':s['active_model_identity'],'reset_digest':s['reset_digest'],'authoritative_digest':identity('grcv4-authoritative-sha256',{'schema_version':'grcv4-authoritative-state-identity-v1','authoritative':s['authoritative']})}.items():r[prefix+'_'+k]=v
 return r

def pack(payloads,source,target,operation='audit:step'):
 ids=[identity('grc-receipt-sha256',v) for v in payloads]
 commit={'schema_version':'grcv4-commit-payload-v1','operation_id':operation,'source_state_digest':state_id(source),'target_state_digest':state_id(target),'emitted_receipt_ids':ids,'target_step_index':target['step_index'],'target_time':target['time']}
 cid=identity('grc-commit-sha256',commit)
 env=[{'schema_version':'grcv4-successful-receipt-envelope-v1','receipt_id':rid,'commit_id':cid,'identity_payload':copy.deepcopy(v)} for v,rid in zip(payloads,ids)]
 return commit,env

def positive(source=None,target=None,payloads=None,dt=0.25,ledger=None):
 source=scientific() if source is None else copy.deepcopy(source)
 if target is None:
  target=copy.deepcopy(source);target.update(step_index=4,time=1);target['authoritative']['C']=[1.25,1.75]
 if payloads is None:payloads=[{'schema_version':'grcv4-step-commit-receipt-v1','core':core(source,target)}]
 commit,env=pack(payloads,source,target)
 if ledger is None:
  _,ledger=pack([{'schema_version':'grcv4-step-commit-receipt-v1','core':core(source,source,'audit:historical')}],source,source,'audit:historical')
 data={'schema_version':'grcv4-step-result-v1','step_index':target['step_index'],'time':target['time'],'events':[],'observables':{},'active_profile_id':target['active_model_identity'],'active_model_identity':target['active_model_identity'],'operation_disposition':'committed','solver_disposition':'valid_root','committed':True,'commit_id':env[0]['commit_id'],'failure':None,'emitted_receipts':env}
 args={'request':req(dt),'prestate':source,'poststate':target,'pre_ledger':ledger,'post_ledger':copy.deepcopy(ledger)+copy.deepcopy(env),'observed_stage':'commit','observed_code':None,'observed_solver':'valid_root','commit_payload':commit}
 return data,args

def negative(stage='admission',code='invalid_duration',solver=None,dt=-1,ledger=None):
 source=scientific();ledger=[] if ledger is None else copy.deepcopy(ledger)
 fid={'schema_version':'grcv4-failure-receipt-v1','operation_id':'audit:step','stage':stage,'code':code,'source_state_digest':state_id(source),'observed_poststate_digest':state_id(source)}
 receipt={'schema_version':'grcv4-failure-receipt-envelope-v1','receipt_id':identity('grc-receipt-sha256',fid),'identity_payload':fid}
 failure={'stage':stage,'code':code,'solver_disposition':solver,'message':'audit hand-authored outcome','prestate_digest':state_id(source),'poststate_digest':state_id(source),'pre_lifecycle_digest':life_id(source,ledger),'post_lifecycle_digest':life_id(source,ledger),'failure_receipt':copy.deepcopy(receipt)}
 data={'schema_version':'grcv4-step-result-v1','step_index':3,'time':0.75,'events':[],'observables':{},'active_profile_id':source['active_model_identity'],'active_model_identity':source['active_model_identity'],'operation_disposition':'rejected','solver_disposition':solver,'committed':False,'commit_id':None,'failure':failure,'emitted_receipts':[receipt]}
 args={'request':req(dt),'prestate':source,'poststate':copy.deepcopy(source),'pre_ledger':ledger,'post_ledger':copy.deepcopy(ledger),'observed_stage':stage,'observed_code':code,'observed_solver':solver}
 return data,args

def reconstruct(d,direct=False):
 if not direct:return st.GRCV4StepResult.from_payload(d)
 x=copy.deepcopy(d);x.pop('schema_version');x['events']=[GRCEvent(**e) if isinstance(e,dict) else e for e in x['events']]
 return st.GRCV4StepResult(**x)
def bind(d,args):return sp.bind_step_result(reconstruct(d),**args)
def good_bind(d,args):
 v=bind(d,args)
 assert type(v.request_bytes) is bytes
 assert v.request_bytes==args['request'].to_canonical_bytes()
 assert json.loads(v.prestate_bytes)==args['prestate']
 assert json.loads(v.poststate_bytes)==args['poststate']
 return None

# Independent baseline fixtures and exact preimages.
for name,f in [('committed',positive),('rejected',negative)]:
 d,args=f();test('baseline:'+name,lambda d=d,args=args:good_bind(d,args),category='positive_composition')
 r=reconstruct(d)
 test('canonical_roundtrip:'+name,lambda r=r:None if st.GRCV4StepResult.from_canonical_bytes(r.to_canonical_bytes())==r else (_ for _ in ()).throw(AssertionError()),category='positive_composition')

